// Variable für die Klick-Verzögerung (Debounce)
let debounceTimer;

// Bindet die Funktion global an das Fenster, damit das HTML-Feld sie findet
window.sendValue = function (val) {
  // 1. Wert sofort an Appsmith senden
  appsmith.updateModel({
    value: Number(val)
  });

  // 2. Vorherigen Timer löschen (Debounce)
  clearTimeout(debounceTimer);

  // 3. Neuen Timer starten: Wartet 500ms nach dem letzten Klick
  debounceTimer = setTimeout(() => {
    appsmith.triggerEvent("onChange");
  }, 500);
};
appsmith.onModelChange(() => {
  const isDisabled = appsmith.model.isDisabled;
  const inputEl = document.getElementById("numInput");
  if (inputEl) {
    inputEl.disabled = isDisabled;
    inputEl.style.backgroundColor = isDisabled ? "#f2f4f7" : "#ffffff";

    // NEU: Aktualisiert das HTML-Feld, wenn sich der Wert von außen (per JS) ändert
    if (appsmith.model.value !== undefined) {
      inputEl.value = appsmith.model.value;
    }
  }
});

